  color: var(--gray);
  font-size: 0.8rem;
  cursor: pointer;
  transition: all var(--transition);
}
.footer-country-btn:hover { border-color: var(--red); color: var(--white); }
.footer-country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  background: var(--black);
  border: 1px solid var(--black-lighter);
  border-radius: 4px;
  min-width: 160px;
  display: none;
  z-index: 10;
  margin-bottom: 4px;
}
.footer-country-dropdown.open { display: block; }
.footer-country-dropdown a {
  display: block;
  padding: 10px 16px;
  color: var(--gray);
  font-size: 0.8rem;
  transition: all var(--transition);
}
.footer-country-dropdown a:hover { background: var(--black-lighter); color: var(--white); }
.footer-bottom {
  border-top: 1px solid var(--black-lighter);
  margin-top: 40px;
  padding: 24px;
  text-align: center;
  font-size: 0.75rem;
  color: var(--gray-dark);
}

@media (max-width: 768px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 28px; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

/* --- Page-specific helpers --- */
.page-hero {
  padding: 100px 24px 60px;
  text-align: center;
  position: relative;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, var(--red-glow) 0%, transparent 70%);
  opacity: 0.3;
  pointer-events: none;
}
.page-hero h1 { position: relative; z-index: 1; }
.page-hero h1 span { color: var(--red); }
.page-hero p { position: relative; z-index: 1; color: var(--gray); max-width: 550px; margin: 16px auto 0; font-size: 1.05rem; }

/* --- Unlimited Access highlight --- */
.unlimited-access {
  text-align: center;
  max-width: 600px;
  margin: 0 auto;
}
.unlimited-access h2 { margin-bottom: 16px; }
.unlimited-access h2 span { color: var(--red); }
.unlimited-access p { color: var(--gray); font-size: 1.05rem; margin-bottom: 24px; }

/* --- CTA Sections --- */
.cta-section {
  text-align: center;
  padding: 80px 24px;
  background: var(--red);
}
.cta-section h2 { margin-bottom: 16px; }
.cta-section p { font-size: 1.05rem; margin-bottom: 28px; opacity: 0.9; }
.cta-section .btn-outline { border-color: var(--white); color: var(--white); }
.cta-section .btn-outline:hover { background: var(--white); color: var(--red); }

/* --- Workout Types (digital page) --- */
.workout-types-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 900px;
  margin: 0 auto;
}
.workout-type-card {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  border-radius: 8px;
  padding: 36px 24px;
  text-align: center;
  transition: all var(--transition);
}
.workout-type-card:hover {
  border-color: var(--red);
  transform: translateY(-3px);
}
.workout-type-card .wt-icon { font-size: 2.5rem; color: var(--red); margin-bottom: 12px; }
.workout-type-card h3 { font-size: 1rem; margin-bottom: 8px; }
.workout-type-card p { color: var(--gray); font-size: 0.85rem; }

@media (max-width: 640px) {
  .workout-types-grid { grid-template-columns: 1fr; }
}

/* --- Scrollbar --- */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--black); }
::-webkit-scrollbar-thumb { background: var(--black-lighter); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--red); }

/* --- Selection --- */
::selection { background: var(--red); color: var(--white); }
