/* ============================================
   RedRoom Fitness — Global Styles
   ============================================ */

/* --- Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Oswald:wght@400;500;600;700&display=swap');

/* --- CSS Variables --- */
:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --red-glow: rgba(255, 0, 0, 0.25);
  --black: #141414;
  --black-light: #1E1E1E;
  --black-lighter: #2A2A2A;
  --white: #FFFFFF;
  --gray: #B0B0B0;
  --gray-dark: #666;
  --font-head: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --container: 1200px;
  --transition: 0.3s ease;
}

/* --- Reset --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: var(--font-body);
  background: var(--black);
  color: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input { font-family: inherit; }

/* --- Utility --- */
.container { max-width: var(--container); margin: 0 auto; padding: 0 24px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-head);
  text-transform: uppercase;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: 0.02em;
}
h1 { font-size: clamp(2.4rem, 5vw, 4.5rem); }
h2 { font-size: clamp(1.8rem, 4vw, 3.2rem); }
h3 { font-size: clamp(1.3rem, 2.5vw, 1.8rem); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-head);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 14px 36px;
  border-radius: 4px;
  transition: all var(--transition);
  font-size: 0.95rem;
}
.btn-primary {
  background: var(--red);
  color: var(--white);
}
.btn-primary:hover {
  background: var(--red-dark);
  box-shadow: 0 0 24px var(--red-glow);
}
.btn-outline {
  border: 2px solid var(--white);
  color: var(--white);
  background: transparent;
}
.btn-outline:hover {
  background: var(--white);
  color: var(--black);
}
.btn-lg { padding: 18px 48px; font-size: 1.1rem; }

/* --- Top Bar Promo --- */
.top-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 24px;
  font-family: var(--font-head);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.top-bar a { color: var(--white); text-decoration: underline; margin-left: 8px; }
.top-bar a:hover { opacity: 0.8; }

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--black-lighter);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  height: 72px;
}
.nav-logo {
  font-family: var(--font-head);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--white);
  white-space: nowrap;
}
.nav-logo span { color: var(--red); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
}
.nav-links a {
  font-family: var(--font-head);
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray);
  transition: color var(--transition);
  white-space: nowrap;
}
.nav-links a:hover, .nav-links a.active { color: var(--white); }
.nav-book {
  background: var(--red);
  color: var(--white) !important;
  padding: 8px 20px;
  border-radius: 3px;
  font-weight: 600 !important;
}
.nav-book:hover { background: var(--red-dark) !important; }
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: all var(--transition);
}
.nav-toggle.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav-toggle.open span:nth-child(2) { opacity: 0; }
.nav-toggle.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* Mobile nav */
@media (max-width: 1024px) {
  .nav-toggle { display: flex; }
  .nav-links {
    position: fixed;
    top: 72px;
    left: 0;
    right: 0;
    bottom: 0;
    background: var(--black);
    flex-direction: column;
    align-items: flex-start;
    padding: 32px 24px;
    gap: 20px;
    transform: translateX(100%);
    transition: transform var(--transition);
    overflow-y: auto;
  }
  .nav-links.open { transform: translateX(0); }
  .nav-links a { font-size: 1rem; }
}

/* --- Hero --- */
.hero {
  position: relative;
  min-height: 70vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  padding: 80px 24px;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, var(--red-glow) 0%, transparent 70%);
  opacity: 0.4;
  pointer-events: none;
}
.hero-content { position: relative; z-index: 1; max-width: 800px; }
.hero h1 { margin-bottom: 20px; }
.hero h1 span { color: var(--red); }
.hero p {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--gray);
  margin-bottom: 32px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}
.hero-buttons { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* --- Section --- */
.section {
  padding: 80px 24px;
}
.section-dark { background: var(--black-light); }
.section-red { background: var(--red); }
.section-gray { background: var(--black-lighter); }
.section-header {
  text-align: center;
  margin-bottom: 48px;
}
.section-header h2 { margin-bottom: 16px; }
.section-header h2 span { color: var(--red); }
.section-header p {
  color: var(--gray);
  max-width: 600px;
  margin: 0 auto;
  font-size: 1.05rem;
}

/* --- Community Promo --- */
.community-promo {
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.community-promo h2 { margin-bottom: 20px; }
.community-promo h2 span { color: var(--red); }
.community-promo p { color: var(--gray); margin-bottom: 28px; font-size: 1.05rem; }

/* --- Two Ways --- */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  max-width: 900px;
  margin: 0 auto;
}
.two-ways-card {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  border-radius: 8px;
  padding: 48px 32px;
  text-align: center;
  transition: all var(--transition);
}
.two-ways-card:hover {
  border-color: var(--red);
  box-shadow: 0 0 30px var(--red-glow);
  transform: translateY(-4px);
}
.two-ways-card .icon {
  font-size: 3rem;
  margin-bottom: 16px;
  color: var(--red);
}
.two-ways-card h3 { margin-bottom: 12px; }
.two-ways-card h3 span { color: var(--red); }
.two-ways-card p { color: var(--gray); font-size: 0.95rem; }

@media (max-width: 640px) {
  .two-ways-grid { grid-template-columns: 1fr; }
}

/* --- Studio Experience --- */
.studio-experience {
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.studio-experience h2 { margin-bottom: 20px; }
.studio-experience h2 span { color: var(--red); }
.studio-experience p { color: var(--gray); margin-bottom: 28px; font-size: 1.05rem; }

/* --- Free Trial CTA --- */
.free-trial {
  text-align: center;
  background: var(--red);
  padding: 80px 24px;
}
.free-trial h2 { margin-bottom: 12px; }
.free-trial p { font-size: 1.1rem; margin-bottom: 28px; opacity: 0.9; }
.free-trial .btn-outline { border-color: var(--white); color: var(--white); }
.free-trial .btn-outline:hover { background: var(--white); color: var(--red); }

/* --- Lifestyle Carousel --- */
.carousel-section { overflow: hidden; }
.carousel-track-wrapper {
  position: relative;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/7;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--black-light);
  position: relative;
  overflow: hidden;
}
.carousel-slide-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 12px;
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray);
  font-size: 0.9rem;
}
.carousel-slide-inner .slide-icon {
  font-size: 2.5rem;
  color: var(--red);
}
.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(20, 20, 20, 0.8);
  border: 1px solid var(--black-lighter);
  color: var(--white);
  font-size: 1.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: all var(--transition);
}
.carousel-arrow:hover { background: var(--red); border-color: var(--red); }
.carousel-arrow.prev { left: 16px; }
.carousel-arrow.next { right: 16px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 20px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--black-lighter);
  border: none;
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-dot.active { background: var(--red); transform: scale(1.2); }

/* --- Method Overview --- */
.method-overview {
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.method-overview h2 { margin-bottom: 20px; }
.method-overview h2 span { color: var(--red); }
.method-overview p { color: var(--gray); font-size: 1.05rem; }

/* --- Weekly Schedule --- */
.schedule-table {
  width: 100%;
  max-width: 700px;
  margin: 0 auto;
  border-collapse: collapse;
  font-family: var(--font-body);
}
.schedule-table thead th {
  font-family: var(--font-head);
  text-transform: uppercase;
  font-size: 0.85rem;
  letter-spacing: 0.08em;
  color: var(--gray);
  padding: 14px 20px;
  text-align: left;
  border-bottom: 2px solid var(--red);
}
.schedule-table tbody td {
  padding: 16px 20px;
  border-bottom: 1px solid var(--black-lighter);
  font-size: 0.95rem;
}
.schedule-table tbody td:first-child {
  font-family: var(--font-head);
  text-transform: uppercase;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--white);
}
.schedule-table tbody td:last-child { color: var(--gray); }
.schedule-table tbody tr:hover { background: var(--black-light); }
.schedule-table tbody tr:hover td:last-child { color: var(--red); }

/* --- Floor / Treadmill Toggle --- */
.toggle-section { text-align: center; }
.toggle-section h2 { margin-bottom: 12px; }
.toggle-section h2 span { color: var(--red); }
.toggle-section > p { color: var(--gray); margin-bottom: 28px; }
.toggle-group {
  display: inline-flex;
  background: var(--black-lighter);
  border-radius: 6px;
  overflow: hidden;
  margin-bottom: 36px;
}
.toggle-btn {
  padding: 12px 32px;
  font-family: var(--font-head);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.9rem;
  color: var(--gray);
  background: transparent;
  transition: all var(--transition);
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}
.toggle-btn:hover:not(.active) { color: var(--white); }
.toggle-content { display: none; text-align: left; max-width: 700px; margin: 0 auto; }
.toggle-content.active { display: block; }
.toggle-content h3 {
  margin-bottom: 16px;
  color: var(--red);
}
.toggle-content p { color: var(--gray); font-size: 1.05rem; line-height: 1.7; }

/* --- Instructor Grid --- */
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}
.filter-btn {
  padding: 10px 24px;
  font-family: var(--font-head);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.8rem;
  border: 1px solid var(--black-lighter);
  border-radius: 4px;
  color: var(--gray);
  background: var(--black-light);
  transition: all var(--transition);
}
.filter-btn.active {
  border-color: var(--red);
  background: var(--red);
  color: var(--white);
}
.filter-btn:hover:not(.active) {
  border-color: var(--red);
  color: var(--white);
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
  max-width: var(--container);
  margin: 0 auto;
}
.instructor-card {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 8px 30px var(--red-glow);
}
.instructor-photo {
  aspect-ratio: 1;
  background: var(--black-lighter);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  color: var(--red);
}
.instructor-info { padding: 20px; }
.instructor-info h3 {
  font-size: 1.1rem;
  margin-bottom: 6px;
}
.instructor-location {
  color: var(--red);
  font-size: 0.8rem;
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 12px;
}
.instructor-book {
  display: inline-flex;
  font-family: var(--font-head);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.75rem;
  color: var(--red);
  transition: color var(--transition);
}
.instructor-book:hover { color: var(--white); }

/* --- FAQ Accordion --- */
.faq-list {
  max-width: 750px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--black-lighter);
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 20px 0;
  font-family: var(--font-head);
  font-size: 1.05rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-icon {
  font-size: 1.4rem;
  transition: transform var(--transition);
  flex-shrink: 0;
  color: var(--red);
}
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-answer-inner {
  padding-bottom: 20px;
  color: var(--gray);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* --- Digital Features --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
  max-width: var(--container);
  margin: 0 auto;
}
.feature-card {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  border-radius: 8px;
  padding: 36px 28px;
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: var(--red);
  box-shadow: 0 0 20px var(--red-glow);
  transform: translateY(-3px);
}
.feature-card .feature-icon {
  font-size: 2rem;
  color: var(--red);
  margin-bottom: 16px;
}
.feature-card h3 {
  font-size: 1rem;
  margin-bottom: 10px;
}
.feature-card h3 span { color: var(--red); }
.feature-card p { color: var(--gray); font-size: 0.9rem; line-height: 1.6; }

/* --- Newsletter --- */
.newsletter {
  text-align: center;
  padding: 60px 24px;
  border-top: 1px solid var(--black-lighter);
}
.newsletter h3 {
  font-size: 1.3rem;
  margin-bottom: 8px;
}
.newsletter > p {
  color: var(--gray);
  margin-bottom: 24px;
  font-size: 0.95rem;
}
.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 460px;
  margin: 0 auto;
  align-items: flex-start;
}
.newsletter-input-wrap { flex: 1; position: relative; }
.newsletter-input {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid var(--black-lighter);
  border-radius: 4px;
  background: var(--black-light);
  color: var(--white);
  font-size: 0.9rem;
  transition: border-color var(--transition);
}
.newsletter-input:focus {
  outline: none;
  border-color: var(--red);
}
.newsletter-input.error { border-color: #ff4444; }
.newsletter-input.success { border-color: #44ff44; }
.newsletter-error {
  position: absolute;
  left: 0;
  bottom: -20px;
  font-size: 0.75rem;
  color: #ff4444;
  display: none;
}
.newsletter-error.show { display: block; }
.newsletter-success {
  display: none;
  color: #44ff44;
  font-size: 0.85rem;
  margin-top: 8px;
}
.newsletter-success.show { display: block; }

@media (max-width: 480px) {
  .newsletter-form { flex-direction: column; }
  .newsletter-form .btn { width: 100%; }
}

/* --- Footer --- */
.footer {
  background: var(--black-light);
  border-top: 1px solid var(--black-lighter);
  padding: 60px 24px 0;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  max-width: var(--container);
  margin: 0 auto;
}
.footer-col h4 {
  font-family: var(--font-head);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 20px;
  color: var(--red);
}
.footer-col a {
  display: block;
  color: var(--gray);
  font-size: 0.85rem;
  margin-bottom: 10px;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-country {
  position: relative;
  display: inline-block;
  margin-top: 8px;
}
.footer-country-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border: 1px solid var(--black-lighter);
  border-radius: 4px;
  background: var(--black);
  color: var(--gray);
  font-size: 0.8rem;
  cursor: pointer;
  transition: all var(--transition);
}
.footer-country-btn:hover { border-color: var(--red); color: var(--white); }
.footer-country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  background: var(--black);
  border: 1px solid var(--black-lighter);
  border-radius: 4px;
  min-width: 160px;
  display: none;
  z-index: 10;
  margin-bottom: 4px;
}
.footer-country-dropdown.open { display: block; }
.footer-country-dropdown a {
  display: block;
  padding: 10px 16px;
  color: var(--gray);
  font-size: 0.8rem;
  transition: all var(--transition);
}
.footer-country-dropdown a:hover { background: var(--black-lighter); color: var(--white); }
.footer-bottom {
  border-top: 1px solid var(--black-lighter);
  margin-top: 40px;
  padding: 24px;
  text-align: center;
  font-size: 0.75rem;
  color: var(--gray-dark);
}

@media (max-width: 768px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 28px; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

/* --- Page-specific helpers --- */
.page-hero {
  padding: 100px 24px 60px;
  text-align: center;
  position: relative;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, var(--red-glow) 0%, transparent 70%);
  opacity: 0.3;
  pointer-events: none;
}
.page-hero h1 { position: relative; z-index: 1; }
.page-hero h1 span { color: var(--red); }
.page-hero p { position: relative; z-index: 1; color: var(--gray); max-width: 550px; margin: 16px auto 0; font-size: 1.05rem; }

/* --- Unlimited Access highlight --- */
.unlimited-access {
  text-align: center;
  max-width: 600px;
  margin: 0 auto;
}
.unlimited-access h2 { margin-bottom: 16px; }
.unlimited-access h2 span { color: var(--red); }
.unlimited-access p { color: var(--gray); font-size: 1.05rem; margin-bottom: 24px; }

/* --- CTA Sections --- */
.cta-section {
  text-align: center;
  padding: 80px 24px;
  background: var(--red);
}
.cta-section h2 { margin-bottom: 16px; }
.cta-section p { font-size: 1.05rem; margin-bottom: 28px; opacity: 0.9; }
.cta-section .btn-outline { border-color: var(--white); color: var(--white); }
.cta-section .btn-outline:hover { background: var(--white); color: var(--red); }

/* --- Workout Types (digital page) --- */
.workout-types-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 900px;
  margin: 0 auto;
}
.workout-type-card {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  border-radius: 8px;
  padding: 36px 24px;
  text-align: center;
  transition: all var(--transition);
}
.workout-type-card:hover {
  border-color: var(--red);
  transform: translateY(-3px);
}
.workout-type-card .wt-icon { font-size: 2.5rem; color: var(--red); margin-bottom: 12px; }
.workout-type-card h3 { font-size: 1rem; margin-bottom: 8px; }
.workout-type-card p { color: var(--gray); font-size: 0.85rem; }

@media (max-width: 640px) {
  .workout-types-grid { grid-template-columns: 1fr; }
}

/* --- Scrollbar --- */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--black); }
::-webkit-scrollbar-thumb { background: var(--black-lighter); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--red); }

/* --- Selection --- */
::selection { background: var(--red); color: var(--white); }

